class Solution:
    def minDayskVariants(self, points: List[List[int]], k: int) -> int:
        best = float('inf')
        xs = [p[0] for p in points]
        ys = [p[1] for p in points]
        for cx in range(min(xs) - 200, max(xs) + 201):
            for cy in range(min(ys) - 200, max(ys) + 201):
                ds = sorted(abs(cx - x) + abs(cy - y) for x, y in points)
                best = min(best, ds[k - 1])
        return best

