        int minX = 101, maxX = 0, minY = 101, maxY = 0;
        for (auto& p : points) {
            minX = min(minX, p[0]); maxX = max(maxX, p[0]);
            minY = min(minY, p[1]); maxY = max(maxY, p[1]);
        }
        int best = INT_MAX;
        vector<int> ds;
        for (int cx = minX - 200; cx <= maxX + 200; ++cx) {
            for (int cy = minY - 200; cy <= maxY + 200; ++cy) {
                ds.clear();
                for (auto& p : points)
                    ds.push_back(abs(cx - p[0]) + abs(cy - p[1]));
                nth_element(ds.begin(), ds.begin() + k - 1, ds.end());
                best = min(best, ds[k - 1]);
            }
        }
        return best;
    }
};

