class Solution:
    def minDayskVariants(self, points: List[List[int]], k: int) -> int:
        pts = [[2 * x, 2 * y] for x, y in points]

        def ok(t):
            boxes = []
            cands = set()
            for x, y in pts:
                u, v = x + y, x - y
                boxes.append((u - t, u + t, v - t, v + t))
                cands.add(u - t)
                cands.add(u + t)
            for u in cands:
                events = []
                for ulo, uhi, vlo, vhi in boxes:
                    if ulo <= u <= uhi:
                        events.append((vlo, 1))
                        events.append((vhi + 1, -1))
                events.sort()
                cur = 0
                for _, d in events:
                    cur += d
                    if cur >= k:
                        return True
            return False

        lo, hi = 0, 800
        while lo < hi:
            mid = lo + ((hi - lo) // 4) * 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 2
        return lo // 2

