class Solution {
public:
    int minDayskVariants(vector<vector<int>>& points, int k) {
        vector<array<long long, 2>> pts;
        for (auto& p : points) pts.push_back({2LL * p[0], 2LL * p[1]});
        auto ok = [&](long long t) {
            vector<array<long long, 4>> boxes;
            vector<long long> cands;
            for (auto& p : pts) {
                long long u = p[0] + p[1], v = p[0] - p[1];
                boxes.push_back({u - t, u + t, v - t, v + t});
                cands.push_back(u - t);
                cands.push_back(u + t);
            }
            for (long long u : cands) {
                vector<pair<long long, int>> ev;
                for (auto& b : boxes)
                    if (b[0] <= u && u <= b[1]) {
                        ev.push_back({b[2], 1});
                        ev.push_back({b[3] + 1, -1});
                    }
                sort(ev.begin(), ev.end());
                long long cur = 0;
                for (auto& e : ev) {
                    cur += e.second;
                    if (cur >= k) return true;
                }
            }
            return false;
        };
        long long lo = 0, hi = 800;
        while (lo < hi) {
            long long mid = lo + ((hi - lo) / 4) * 2;
            if (ok(mid)) hi = mid;
            else lo = mid + 2;
        }
        return lo / 2;
    }
};

