class Solution {
    public int minDayskVariants(int[][] points, int k) {
        int n = points.length;
        long[][] pts = new long[n][2];
        for (int i = 0; i < n; ++i) {
            pts[i][0] = 2L * points[i][0];
            pts[i][1] = 2L * points[i][1];
        }
        long lo = 0, hi = 800;
        while (lo < hi) {
            long mid = lo + ((hi - lo) / 4) * 2;
            if (ok(pts, mid, k)) hi = mid;
            else lo = mid + 2;
        }
        return (int) (lo / 2);
    }

    private boolean ok(long[][] pts, long t, int k) {
        List<long[]> boxes = new ArrayList<>();
        List<Long> cands = new ArrayList<>();
        for (long[] p : pts) {
            long u = p[0] + p[1], v = p[0] - p[1];
            boxes.add(new long[]{u - t, u + t, v - t, v + t});
            cands.add(u - t);
            cands.add(u + t);
        }
        for (long u : cands) {
            List<long[]> ev = new ArrayList<>();
            for (long[] b : boxes)
                if (b[0] <= u && u <= b[1]) {
                    ev.add(new long[]{b[2], 1});
                    ev.add(new long[]{b[3] + 1, -1});
                }
            ev.sort((a, c) -> Long.compare(a[0], c[0]));
            long cur = 0;
            for (long[] e : ev) {
                cur += e[1];
                if (cur >= k) return true;
            }
        }
        return false;
    }
}

